103	  &= \mathbb{E}[TY] - \sum_j \bigl(\mathrm{ct}_j/q_j\bigr)\,\mathbb{E}[Y\cdot D_j^*]\\
104	  &= \mu_{TY} - \sum_j \mathrm{ct}_j\,\mathrm{cy}_j/q_j.
105	\end{align*}
106	\end{proof}
